tools.example:
rate = 0.06/12;
n = 360;
payment = 1500;
pv = pvfix(rate, n, payment)
fprintf('A 30-year 1500/month stream at 6%% is worth %.2f today\n', pv);
pvDue = pvfix(rate, n, payment, 0, 1);

monthlyRate = 0.07/12;
months = 25*12;
fv = fvfix(monthlyRate, months, 500, 10000);
fprintf('Value after 25 years: %.2f\n', fv);
fvDue = fvfix(monthlyRate, months, 500, 10000, 1);
fprintf('Paying at period start adds %.2f\n', fvDue - fv);

cf = [-100000; 25000; 30000; 35000; 40000; 20000];
[r, allRates] = irr(cf);
fprintf('IRR = %.4f (%.2f%%)\n', r, r*100);
npvCheck = sum(cf ./ (1+r).^(0:numel(cf)-1)');
fprintf('NPV at the IRR: %.6f\n', npvCheck);

cf = [-50000 12000 18000 22000 17000];
npv = pvvar(cf, 0.08);
fprintf('NPV at 8%%: %.2f\n', npv);
dates = datetime(2024, [1 4 9 12 18], 15);
npvDated = pvvar(cf, 0.08, dates);
fprintf('With actual dates: %.2f\n', npvDated);

S = 100; K = 105; r = 0.04; T = 0.5; sigma = 0.25; q = 0.02;
[c, p] = blsprice(S, K, r, T, sigma, q);
fprintf('Call %.4f, Put %.4f\n', c, p);
parity = c - p - (S*exp(-q*T) - K*exp(-r*T));
fprintf('Put-call parity residual: %.2e\n', parity);
[cd, pd] = blsdelta(S, K, r, T, sigma, q);
vega = blsvega(S, K, r, T, sigma, q);

S = 100; r = 0.04; T = 0.25;
strikes = (85:5:115)';
marketCalls = [16.2 11.8 7.9 4.8 2.6 1.3 0.6]';
iv = blsimpv(S, strikes, r, T, marketCalls, [], 0, [], {'call'});
plot(strikes, iv*100, 'o-'); grid on
xlabel('Strike'); ylabel('Implied volatility (%)')
title('Volatility smile')

rng(0)
returns = randn(500, 5) .* [0.01 0.015 0.02 0.008 0.012] + [4e-4 5e-4 7e-4 2e-4 3e-4];
p = Portfolio('AssetList', {'A','B','C','D','E'}, 'RiskFreeRate', 0.0001);
p = estimateAssetMoments(p, returns);
p = setDefaultConstraints(p);      % long only, fully invested
pwgt = estimateFrontier(p, 20);
[prsk, pret] = estimatePortMoments(p, pwgt);
plot(prsk, pret, 'o-'); xlabel('Risk'); ylabel('Return')

p = Portfolio('AssetMean', [0.05 0.08 0.12]', ...
    'AssetCovar', [0.04 0.01 0.005; 0.01 0.09 0.02; 0.005 0.02 0.16]);
p = setDefaultConstraints(p);
pwgt = estimateFrontier(p, 15);
[risk, ret] = estimatePortMoments(p, pwgt);
plotFrontier(p, 15)
wSharpe = estimateMaxSharpeRatio(p);
fprintf('Max Sharpe weights: %s\n', mat2str(round(wSharpe', 4)));

p = Portfolio('AssetMean', [0.06 0.10 0.14]', ...
    'AssetCovar', [0.03 0.008 0.004; 0.008 0.08 0.015; 0.004 0.015 0.18], ...
    'RiskFreeRate', 0.02);
p = setDefaultConstraints(p);
w = estimateMaxSharpeRatio(p);
[risk, ret] = estimatePortMoments(p, w);
fprintf('Sharpe = %.4f at risk %.4f, return %.4f\n', ...
    (ret - p.RiskFreeRate)/risk, risk, ret);

prices = 100 * cumprod(1 + 0.01*randn(500, 3));
simpleRet = tick2ret(prices);
logRet = tick2ret(prices, 'Method', 'continuous');
fprintf('Annualized volatility: %s\n', ...
    mat2str(round(std(logRet)*sqrt(252), 4)));
pricesBack = ret2tick(simpleRet, 'StartPrice', prices(1,:));

rng(1)
equity = 100 * cumprod(1 + 0.008*randn(1000,1) + 0.0004);
[mdd, idx] = maxdrawdown(equity);
fprintf('Max drawdown %.2f%% from index %d to %d\n', mdd*100, idx(1), idx(2));
plot(equity); hold on
plot(idx, equity(idx), 'ro-', 'LineWidth', 2)
fprintf('Sharpe ratio: %.3f\n', sharpe(tick2ret(equity), 0));

rng(2)
ret = 0.0005 + 0.01*randn(1000, 3);
rf = 0.0001;
sr = sharpe(ret, rf);
fprintf('Per-period Sharpe: %s\n', mat2str(round(sr, 4)));
fprintf('Annualized: %s\n', mat2str(round(sr*sqrt(252), 3)));
sortinoRatio = sortino(ret, rf);

rng(0)
prices = 100 * cumprod(1 + 0.01*randn(400,1));
fast = movavg(prices, 'exponential', 12);
slow = movavg(prices, 'exponential', 26);
plot(1:400, prices, 1:400, fast, 1:400, slow)
legend('price','EMA12','EMA26')
crossUp = find(diff(sign(fast - slow)) > 0);
fprintf('%d bullish crossovers\n', numel(crossUp));

load Data_Airline
y = log(DataTimeTable.PSSG);
Mdl = arima('Constant', 0, 'D', 1, 'Seasonality', 12, ...
    'MALags', 1, 'SMALags', 12);
EstMdl = estimate(Mdl, y);
[yF, yMSE] = forecast(EstMdl, 24, 'Y0', y);
ub = yF + 1.96*sqrt(yMSE); lb = yF - 1.96*sqrt(yMSE);
plot(1:numel(y), y, numel(y)+(1:24), yF, 'r', ...
     numel(y)+(1:24), [ub lb], 'k--')

load Data_EquityIdx
r = 100 * price2ret(DataTimeTable.NASDAQ);
Mdl = garch('GARCHLags', 1, 'ARCHLags', 1, 'Offset', NaN, 'Distribution', 't');
EstMdl = estimate(Mdl, r);
v = infer(EstMdl, r);
plot(sqrt(v)); ylabel('Conditional volatility (%)')
vF = forecast(EstMdl, 20, 'Y0', r);
fprintf('Persistence: %.4f\n', EstMdl.GARCH{1} + EstMdl.ARCH{1});

load Data_Airline
y = log(DataTimeTable.PSSG);
Mdl = arima(2, 1, 1);
[EstMdl, EstParamCov, logL] = estimate(Mdl, y, 'Display', 'full');
numParams = sum(any(EstParamCov));
[aic, bic] = aicbic(logL, numParams, numel(y));
fprintf('AIC %.2f, BIC %.2f\n', aic, bic);

load Data_Airline
y = log(DataTimeTable.PSSG);
EstMdl = estimate(arima('D', 1, 'Seasonality', 12, 'MALags', 1, 'SMALags', 12), y);
h = 36;
[yF, yMSE] = forecast(EstMdl, h, 'Y0', y);
ci = yF + 1.96*sqrt(yMSE).*[-1 1];
n = numel(y);
plot(1:n, y, 'b', n+(1:h), yF, 'r', n+(1:h), ci, 'k--')
legend('history','forecast','95% CI')

rng(1)
EstMdl = estimate(garch(1,1), r, 'Display', 'off');
[V, Y] = simulate(EstMdl, 250, 'NumPaths', 5000, 'Y0', r);
cumRet = sum(Y, 1)';
VaR95 = -prctile(cumRet, 5);
fprintf('1-year 95%% VaR: %.2f%%\n', VaR95);
histogram(cumRet, 60)

EstMdl = estimate(arima(2,1,1), y, 'Display', 'off');
[e, v, logL] = infer(EstMdl, y);
stdRes = e ./ sqrt(v);
subplot(2,2,1), plot(stdRes), title('Standardized residuals')
subplot(2,2,2), qqplot(stdRes)
subplot(2,2,3), autocorr(stdRes)
subplot(2,2,4), autocorr(stdRes.^2)
[h, p] = lbqtest(stdRes, 'Lags', 20);
fprintf('Ljung-Box p = %.4f\n', p);

load Data_JAustralian
y = DataTimeTable.EXCH;
[h, p, stat, cv] = adftest(y, 'Model', 'ARD', 'Lags', 0:4);
disp(table((0:4)', h', p', stat', cv', ...
    'VariableNames', {'Lags','Reject','pValue','Stat','CritVal'}))
[hd, pd] = adftest(diff(y), 'Model', 'ARD', 'Lags', 2);
fprintf('Differenced series stationary: %d (p = %.4f)\n', hd, pd);

load Data_JAustralian
y = DataTimeTable.EXCH;
[hK, pK] = kpsstest(y, 'Lags', 0:4, 'Trend', false);
[hA, pA] = adftest(y, 'Model', 'ARD', 'Lags', 0:4);
disp(table((0:4)', hA', pA', hK', pK', ...
    'VariableNames', {'Lags','ADFreject','ADFp','KPSSreject','KPSSp'}))

EstMdl = estimate(arima(2,0,1), y, 'Display', 'off');
e = infer(EstMdl, y);
[h, p, stat] = lbqtest(e, 'Lags', [5 10 15], 'DOF', [2 7 12]);
disp(table([5;10;15], h', p', stat', ...
    'VariableNames', {'Lags','Reject','pValue','Stat'}))
[h2, p2] = lbqtest(e.^2, 'Lags', 10);
fprintf('ARCH effects remaining: %d (p = %.4f)\n', h2, p2);

load Data_EquityIdx
r = 100 * price2ret(DataTimeTable.NASDAQ);
e = r - mean(r);
[h, p, stat] = archtest(e, 'Lags', [1 5 10]);
disp(table([1;5;10], h', p', stat', ...
    'VariableNames', {'Lags','Reject','pValue','Stat'}))
if any(h)
    Mdl = estimate(garch(1,1), r, 'Display', 'off');
end

load Data_USEconModel
Y = [DataTimeTable.CPIAUCSL DataTimeTable.UNRATE DataTimeTable.FEDFUNDS];
Y = Y(~any(ismissing(Y), 2), :);
Mdl = varm(3, 4);
Mdl.SeriesNames = {'CPI','Unemployment','FedFunds'};
EstMdl = estimate(Mdl, Y);
summarize(EstMdl)
[h, p] = gctest(EstMdl);
irf(EstMdl, 'NumObs', 20);

load Data_Airline
y = log(DataTimeTable.PSSG);
subplot(2,1,1), autocorr(y, 'NumLags', 40), title('Levels')
dy = diff(y, 1);
subplot(2,1,2), autocorr(dy, 'NumLags', 40), title('Differenced')
[acf, lags, bounds] = autocorr(dy, 'NumLags', 24);
significant = lags(abs(acf) > bounds(1));

load Data_Airline
dy = diff(log(DataTimeTable.PSSG));
subplot(2,1,1), autocorr(dy, 'NumLags', 30)
subplot(2,1,2), parcorr(dy, 'NumLags', 30)
[pacf, lags, bounds] = parcorr(dy, 'NumLags', 30);
fprintf('Lags with significant PACF: %s\n', ...
    mat2str(lags(abs(pacf) > bounds(1))'));
